package com.metabuild.schema.platform;
import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import org.junit.jupiter.api.Test;
class Task20CredentialRevisionMigrationTest {@Test void revisionAndSingletonInvariantsAreDatabaseOwned()throws Exception{String sql=Files.readString(Path.of("src/main/resources/db/migration/platform/V11__credential_revision_and_company_singleton.sql"));assertTrue(sql.contains("credential_revision bigint not null default 0"));assertTrue(sql.contains("mb_user_credential_revision_monotonic"));assertTrue(sql.contains("credential_revision >= 0"));assertTrue(sql.contains("mb_refresh_token add column credential_revision"));assertTrue(sql.contains("mb_company add constraint mb_company_singleton unique"));assertTrue(sql.contains("singleton_key = 1"));}}
